const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Crear ticket - Help Desk</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --panel: #ffffff;
      --line: #d8e0ea;
      --text: #172033;
      --muted: #667085;
      --brand: #0f766e;
      --brand-dark: #115e59;
      --danger: #b42318;
      --ok: #067647;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font-family: "Segoe UI", Arial, sans-serif;
      display: grid;
      place-items: center;
      padding: 28px;
    }
    .shell {
      width: min(940px, 100%);
      display: grid;
      grid-template-columns: .9fr 1.1fr;
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 8px;
      overflow: hidden;
      box-shadow: 0 18px 45px rgba(16, 24, 40, .10);
    }
    .info {
      background: #123c3a;
      color: #fff;
      padding: 34px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 28px;
    }
    .info h1 {
      margin: 0 0 10px;
      font-size: 30px;
      line-height: 1.1;
      letter-spacing: 0;
    }
    .info p { margin: 0; color: #d7efeb; line-height: 1.5; }
    .steps {
      display: grid;
      gap: 12px;
      margin-top: 24px;
    }
    .step {
      border: 1px solid rgba(255,255,255,.22);
      border-radius: 6px;
      padding: 12px;
      color: #eefaf8;
      font-size: 13px;
    }
    form { padding: 34px; }
    h2 { margin: 0 0 6px; font-size: 22px; }
    .hint { margin: 0 0 22px; color: var(--muted); }
    label { display: block; font-weight: 700; margin: 14px 0 7px; }
    input, textarea {
      width: 100%;
      border: 1px solid var(--line);
      border-radius: 6px;
      padding: 11px 12px;
      font: inherit;
      color: var(--text);
      background: #fff;
    }
    textarea { min-height: 150px; resize: vertical; line-height: 1.4; }
    .actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-top: 22px;
    }
    button {
      border: 0;
      border-radius: 6px;
      padding: 11px 16px;
      background: var(--brand);
      color: #fff;
      font-weight: 800;
      cursor: pointer;
    }
    button:hover { background: var(--brand-dark); }
    button:disabled { opacity: .65; cursor: wait; }
    .status { font-weight: 700; font-size: 13px; color: var(--muted); }
    .status.ok { color: var(--ok); }
    .status.error { color: var(--danger); }
    @media (max-width: 760px) {
      body { padding: 16px; place-items: start center; }
      .shell { grid-template-columns: 1fr; }
      .info, form { padding: 24px; }
    }
  </style>
</head>
<body>
  <main class="shell">
    <section class="info">
      <div>
        <h1>Help Desk</h1>
        <p>Registra tu solicitud de soporte con la informacion necesaria para que el equipo tecnico pueda priorizarla y atenderla.</p>
        <div class="steps">
          <div class="step"><strong>1.</strong> Describe el problema con claridad.</div>
          <div class="step"><strong>2.</strong> El sistema asigna prioridad automaticamente.</div>
          <div class="step"><strong>3.</strong> Recibiras confirmacion por correo.</div>
        </div>
      </div>
      <p>Sistema de gestion de tickets</p>
    </section>
    <form id="ticketForm">
      <h2>Crear ticket</h2>
      <p class="hint">Los campos son obligatorios. No incluyas contrasenas ni informacion sensible.</p>

      <label for="nombre">Nombre completo</label>
      <input id="nombre" name="nombre" autocomplete="name" required>

      <label for="correo">Correo electronico</label>
      <input id="correo" name="correo" type="email" autocomplete="email" required>

      <label for="problema">Descripcion del problema</label>
      <textarea id="problema" name="problema" required placeholder="Ejemplo: No puedo ingresar al sistema, aparece error al iniciar sesion..."></textarea>

      <div class="actions">
        <span id="status" class="status">Listo para enviar</span>
        <button id="sendButton" type="submit">Enviar ticket</button>
      </div>
    </form>
  </main>

  <script>
    function webhookBase() {
      return '/webhook/';
    }

    const form = document.getElementById('ticketForm');
    const status = document.getElementById('status');
    const button = document.getElementById('sendButton');

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      button.disabled = true;
      status.className = 'status';
      status.textContent = 'Enviando ticket...';

      const payload = {
        nombre: form.nombre.value.trim(),
        correo: form.correo.value.trim(),
        problema: form.problema.value.trim()
      };

      try {
        const response = await fetch(webhookBase() + 'Ticket-submit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });

        const result = await response.json().catch(() => ({}));
        if (!response.ok || result.success === false) throw new Error(result.message || 'No se pudo registrar');

        form.reset();
        status.className = 'status ok';
        status.textContent = 'Ticket enviado correctamente. Revisa tu correo.';
      } catch (error) {
        status.className = 'status error';
        status.textContent = error.message || 'No se pudo enviar el ticket. Verifica que el workflow este activo.';
      } finally {
        button.disabled = false;
      }
    });
  </script>
</body>
</html>`;

return [{ json: { html } }];
